WITH base AS (SELECT *, CASE WHEN budget >= 4254000 THEN 'High' WHEN budget >= 1377000 THEN 'Medium' ELSE 'Low' END budget_tier, COALESCE(dept_name, 'N/A') dept_name_clean FROM departments WHERE location IS NOT NULL), remaining_keys AS (SELECT dept_name, location FROM base EXCEPT DISTINCT SELECT dept_name, location FROM departments WHERE dept_name IN ('HR', 'Marketing', 'Legal')), kept_rows AS (SELECT s.* FROM base s INNER JOIN remaining_keys k ON s.dept_name = k.dept_name AND s.location = k.location), enriched AS (SELECT *, DENSE_RANK() OVER w_grp budget_dense_rank, COUNT(budget) OVER (PARTITION BY dept_name, location) dept_name_count_budget, DENSE_RANK() OVER (ORDER BY budget DESC) budget_dense_rank_2 FROM kept_rows WINDOW w_grp AS (ORDER BY budget DESC NULLS FIRST)), eligible AS (SELECT s.* FROM enriched s WHERE EXISTS (SELECT 1 FROM employees ch WHERE ch.dept_id = s.id AND ch.salary BETWEEN 69000 AND 148000)) SELECT location, PERCENTILE_APPROX(budget_dense_rank, 0.9) AS budget_dense_rank_p90, ROUND(AVG(budget_dense_rank_2), 2) AS avg_budget_dense_rank_2 FROM eligible GROUP BY 1 ORDER BY avg_budget_dense_rank_2 DESC
